import six
from .exceptions import MessageQueryFunctionAlreadyExists
from .exceptions import FunctionFail
from .exceptions import FunctionWithTooFewParameters
from .exceptions import UnknownFunction

query_functions = {}


def function_on_value(func):
    """
    Decorator for user-defined function (func) that is used to ...

    :param func:
    :return:
    """
    def wrapped_function(*args, **kwargs):
        """

        :param arg:
        :param kwargs:
        :return:
        """
        try:
            result = func(*args, **kwargs)
            return result
        except Exception as err:
            function_failed = FunctionFail(function_raised_exception=err, function=func)
            # print function_failed  # TODO: put into logs
            raise function_failed
    wrapped_function.__wrapped__ = func
    # -------------------------------------------------------------------------------------------------
    # we may define function as:  def min_CA_category()
    # but don't wan't simillar names like:    min_CA_category()    min_ca_category()    MinCaCategory()
    # since that may be painfull debugging "why my function wasn't called"
    # so "name lookup" is based on lowercased names with stripped out underscores
    # -------------------------------------------------------------------------------------------------
    func_lookup_name = func.__name__.lower().replace('_', '')
    if func_lookup_name not in query_functions:
        query_functions[func_lookup_name] = wrapped_function
    else:
        raise MessageQueryFunctionAlreadyExists(func_lookup_name)  # TODO: z funkcji wyciagnac lokalizaje starej i nowej
    return wrapped_function


def function_on_field_value(func):
    """
    Decorator for user-defined function (func) that is used to ...

    :param func:
    :return:
    """
    if six.get_function_code(func).co_argcount == 0:
        raise FunctionWithTooFewParameters(func)

    def wrapped_function(*args, **kwargs):
        """

        :param arg:
        :param kwargs:
        :return:
        """
        try:
            result = func(*args, **kwargs)
            return result
        except Exception as err:
            function_failed = FunctionFail(function_raised_exception=err, function=func)
            # print function_failed  # TODO: put into logs
            raise function_failed
    wrapped_function.__wrapped__ = func
    # -------------------------------------------------------------------------------------------------
    # we may define function as:  def min_CA_category()
    # but don't wan't simillar names like:    min_CA_category()    min_ca_category()    MinCaCategory()
    # since that may be painfull debugging "why my function wasn't called"
    # so "name lookup" is based on lowercased names with stripped out underscores
    # -------------------------------------------------------------------------------------------------
    func_lookup_name = func.__name__.lower().replace('_', '')
    if func_lookup_name not in query_functions:
        query_functions[func_lookup_name] = wrapped_function
    else:
        raise MessageQueryFunctionAlreadyExists(func_lookup_name)  # TODO: z funkcji wyciagnac lokalizaje starej i nowej
    return wrapped_function


def get_registered_query_function(function_name):
    """

    :param function_name:
    :return:
    """
    func_lookup_name = function_name.lower().replace('_', '')
    if func_lookup_name not in query_functions:
        raise UnknownFunction(function_name)
    return query_functions[func_lookup_name]
